func newReading() unsafe.Pointer { return unsafe.Pointer(new(recordcase.Reading)) }

func newNReading(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]recordcase.Reading, n)))
}

func ptrReading(p unsafe.Pointer, c int32) any {
	r := (*recordcase.Reading)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RecordKind))
	case 4:
		return (*string)(unsafe.Pointer(&r.RecordID))
	case 5:
		return &r.Fingerprint
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.Segments
	case 8:
		return &r.WhyItMatters
	case 9:
		return &r.IfNothingChanges
	case 10:
		return &r.ModelIdentifier
	case 11:
		return (*string)(unsafe.Pointer(&r.ProviderID))
	case 12:
		return &r.RequestedAt
	case 13:
		return &r.WrittenAt
	case 14:
		return &r.CreatedAt
	case 15:
		return &r.UpdatedAt
	}
	return nil
}

func valueReading(p unsafe.Pointer, c int32) any {
	r := (*recordcase.Reading)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RecordKind)
	case 4:
		return string(r.RecordID)
	case 5:
		return r.Fingerprint
	case 6:
		return string(r.Status)
	case 7:
		if r.Segments == nil {
			return keel.EmptyJSONArray
		}
		return r.Segments
	case 8:
		if r.WhyItMatters == "" {
			return nil
		}
		return r.WhyItMatters
	case 9:
		if r.IfNothingChanges == "" {
			return nil
		}
		return r.IfNothingChanges
	case 10:
		if r.ModelIdentifier == "" {
			return nil
		}
		return r.ModelIdentifier
	case 11:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 12:
		return r.RequestedAt
	case 13:
		if r.WrittenAt == 0 {
			return nil
		}
		return r.WrittenAt
	case 14:
		return r.CreatedAt
	case 15:
		return r.UpdatedAt
	}
	return nil
}

